                if len(markers) != 1 or not corners:
                    continue
                y, x = markers[0]
                r, c = min(corners, key=lambda z: abs(y-z[0])+abs(x-z[1]))
                for rr in range(r-1, r+2):
                    for cc in range(c-1, c+2):
                        if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] != 0:
                            g[rr][cc] = color
    return g
